document.body.classList.add('autopilot');const api=window.GreenGoClasses,key='greengo-profile-v1';let profile=null,rain={},plans=[],active=null,selected='',weatherSeq=0,weatherStamp=0,auto=false,preview=[],watch=null,trip=null;
