const home=$('page-home');home.replaceChildren();home.innerHTML=`<div class="gg-page-title"><p class="gg-overline">GREENGO / READY BEFORE YOU ARE</p><h1>${t('下一节课，已经安排。','Your next class. Already connected.')}</h1><p>${t('一次设置，一周计划。出发、换乘与教室在一起。','Set up once. A week connected, from departure to classroom.')}</p></div><section id="autoSetup" class="route-card"><h2>${t('建立演示通勤档案','Create a demo travel profile')}</h2><p>${t('模拟登录，无密码或学校账户；选择本机保存后可在此浏览器恢复。','Demo sign-in, no password or university account. Optionally restore on this browser.')}</p><form id="profileForm"><div class="auto-fields"><label>${t('显示名','Display name')}<input id="profileName" maxlength="40" required placeholder="Alex"></label><label>${t('出发地区','Starting area')}<select id="profileOrigin"></select></label><label>${t('首选方式','Preferred mode')}<select id="profileMode"><option value="train">${t('火车','Train')}</option><option value="bus">${t('公交','Bus')}</option><option value="walk">${t('步行','Walk')}</option><option value="cycle">${t('骑行','Cycle')}</option></select></label><label>${t('到教学楼总耗时估计（分钟）','Estimated door-to-building minutes')}<input id="profileMinutes" type="number" min="1" max="240" value="35" required></label><label>${t('课前余量（分钟）','Arrival buffer minutes')}<input id="profileBuffer" type="number" min="0" max="60" value="10" required></label></div><label><input id="profileRemember" type="checkbox"> ${t('在本机记住档案和课程（共享设备勿选）','Remember profile and classes here (avoid shared devices)')}</label><label><input id="profileWeather" type="checkbox"> ${t('允许自动获取天气：发送所选地区坐标至 Open-Meteo','Allow automatic weather checks: send selected area coordinates to Open-Meteo')}</label><label><input id="profileRemind" type="checkbox"> ${t('页面打开时自动提醒出发','Enable departure nudges while this page is open')}</label><button class="primary">${t('进入我的通勤日程','Continue to my commute')}</button></form></section><div id="autoDashboard" hidden><div class="auto-account"><span id="autoWelcome"></span><button id="editProfile" class="outline">${t('修改档案','Edit profile')}</button><button id="forgetProfile" class="outline">${t('退出并删除本机档案','Sign out & forget profile')}</button></div><div id="autoHeadline" class="auto-next" aria-live="polite"></div><p id="autoWeatherState" role="status"></p><p>${t('仅在页面打开时检查提醒；关闭后不会后台推送。','Reminders are checked while the page is open; no background push after closing.')}</p><div id="autoAlert" role="status"></div><div id="autoWeek"></div><section class="route-card" id="autoTrip"><h3>${t('出发后的陪伴','On the way')}</h3><p>${t('开始行程后记录用时。可授权 GPS 在本页内记录轨迹；不上传或保存轨迹。余量以手动剩余分钟计算，不是实时 ETA。','Record elapsed time after starting. Optional GPS records a trace only in this page; no trace upload or storage. Buffer guidance uses manually estimated remaining minutes, not a live ETA.')}</p><div id="tripActions"></div><label>${t('预计还需分钟（手动更新）','Remaining minutes (update manually)')}<input id="tripRemaining" type="number" min="0" max="240" value="35"></label><p id="tripStatus" role="status"></p><p id="gpsStatus" role="status"></p><svg id="tripTrace" viewBox="0 0 300 100" aria-label="${t('本次 GPS 轨迹示意','This trip GPS trace')}" hidden><polyline fill="none" stroke="#19734e" stroke-width="3"/></svg></section></div>`;
