$('profileOrigin').innerHTML=$('area').innerHTML;
const imports=document.createElement('section');imports.className='route-card auto-import';imports.innerHTML=`<h2>${t('导入整学期／一周／单节课表','Import a semester, week or class')}</h2><p>${t('CSV 文件，最多500节，按具体日期列出课程；列名：title,date,start,end,building,room。时间按英国本地时间，building 使用 R16 等编号。支持现有建筑列表，未识别行需修正后再导入。','CSV with up to 500 dated classes. Columns: title,date,start,end,building,room. Use UK local time and codes such as R16. Unrecognised rows must be corrected before import.')}</p><input id="timetableFile" aria-label="${t('选择 CSV 课表','Choose CSV timetable')}" type="file" accept=".csv,text/csv"><div id="importActions"></div><p id="importStatus" role="status"></p><div id="importPreview"></div><button type="button" id="confirmImport" class="primary" hidden>${t('确认导入并生成每日计划','Confirm import & build daily plans')}</button>`;$('classes').before(imports);
function goImport(){location.hash='/classes';imports.scrollIntoView({behavior:'smooth'});}
function save(){try{if(profile?.remember)localStorage.setItem(key,JSON.stringify(profile));else localStorage.removeItem(key);$('saveClasses').checked=!!profile?.remember;$('saveClasses').dispatchEvent(new Event('change'));}catch{$('autoWeatherState').textContent=t('无法保存，当前仅在本页保留。','Storage unavailable; session only.');}}
function applyProfile(){if(!profile)return;$('area').value=profile.origin;$('area').dispatchEvent(new Event('change'));$('preference').value=profile.mode==='walk'?'green':'public';$('travelEstimate').value=profile.minutes;$('arrivalMargin').value=profile.buffer;$('reminderEnabled').checked=false;$('watchWeather').checked=false;for(const id of ['travelEstimate','arrivalMargin','reminderEnabled','watchWeather'])$(id).dispatchEvent(new Event('change'));$('autoWelcome').textContent=t('演示档案：','Demo profile: ')+profile.name+' · '+profile.origin;$('autoSetup').hidden=true;$('autoDashboard').hidden=false;}
function choose(c){const before=location.hash;auto=true;api.select(c.id);auto=false;location.hash=before||'/home';selected=c.id+':'+c.mode+':'+c.from;const mode=c.mode;window.dispatchEvent(new CustomEvent('greengo:mode-selected',{detail:{mode,fromBuilding:c.first?null:c.from}}));}
function rebuild(){if(!profile)return;plans=dailyPlans(api.list(),profile,rain);const next=plans.find(c=>londonEpoch(c.day,c.time)>Date.now());active=next||null;
 $('autoHeadline').replaceChildren();if(!next){const h=document.createElement('h2');h.textContent=t('导入课表，剩下交给计划。','Import the timetable. Connect the week.');$('autoHeadline').append(h,button(t('导入课表 →','Import timetable →'),goImport,'primary'));}else{const h=document.createElement('h2');h.textContent=next.title;const p=document.createElement('p');p.textContent=`${next.day} ${next.time} · ${next.building} · ${next.room||t('教室待补充','Room pending')}`;const main=document.createElement('strong');main.textContent=t('建议出发 ','Suggested departure ')+clock(next.depart);const note=document.createElement('p');note.textContent=`${modeName(next.mode)} · ${next.duration} ${t('分钟估计','min estimated')} · ${next.rain?t('雨天增加余量；请核对建议出行方式','Rain buffer applied; review the suggested mode'):t('交通时长为估计，非真实班次','Estimated travel, not live services')}`;$('autoHeadline').append(p,h,main,note,button(t('查看已衔接的校园导航 →','Open connected campus navigation →'),()=>{choose(next);location.hash='/journey';document.querySelector('#arrivalFlow nav button:nth-child(3)').click();},'primary'),button(t('导入／修改课表','Import / edit classes'),goImport));if(selected!==next.id+':'+next.mode+':'+next.from)choose(next);}
 if(next&&next.day===nowDay())$('autoHeadline').append(button(t('开始行程','Start journey'),()=>{$('tripActions').querySelector('button').click();$('autoTrip').hidden=false;$('autoTrip').scrollIntoView({behavior:'smooth'});},'primary'));
 renderSchedule();tick();}
function renderSchedule(){const week=$('autoWeek');week.replaceChildren();const title=document.createElement('h2');title.textContent=t('每日行程，自动衔接','Your days, connected');week.append(title);
 const months=[...new Set(plans.map(c=>c.day.slice(0,7)))].sort(),weeks=[...new Set(plans.map(c=>academicWeek(c.day)))].sort((a,b)=>a-b);if(monthFilter&&!months.includes(monthFilter))monthFilter='';if(weekFilter&&!weeks.includes(Number(weekFilter))){weeks.push(Number(weekFilter));weeks.sort((a,b)=>a-b);}
 const controls=document.createElement('div');controls.className='schedule-filters';const ml=document.createElement('label');ml.textContent=t('月份','Month');const ms=document.createElement('select');ms.id='scheduleMonth';ms.add(new Option(t('全部月份','All months'),''));for(const m of months)ms.add(new Option(m,m));ms.value=monthFilter;ml.append(ms);
 const wl=document.createElement('label');wl.textContent=t('学周','Teaching week');const ws=document.createElement('select');ws.id='scheduleWeek';ws.add(new Option(t('全部学周','All weeks'),''));for(const n of weeks){const range=weekRange(n);ws.add(new Option(n===0?t('开课前活动','Before teaching starts'):t('第','Week ')+n+t('周','')+' · '+range[0]+' – '+range[1],String(n)));}ws.value=weekFilter;wl.append(ws);ms.onchange=()=>{monthFilter=ms.value;renderSchedule();};ws.onchange=()=>{weekFilter=ws.value;renderSchedule();};
 controls.append(ml,wl,button(t('本周','This week'),()=>{monthFilter='';weekFilter=String(academicWeek(nowDay()));renderSchedule();}),button(t('显示全部','Show all'),()=>{monthFilter='';weekFilter='';renderSchedule();}));week.append(controls);const note=document.createElement('p');note.className='schedule-filter-note';note.textContent=t('2026年9月28日起为第1周，每周一递增；月份与学周条件同时生效。筛选只改变列表，不改变下一节课建议。','Week 1 starts 28 September 2026; weeks advance every Monday. Month and week filters apply together. Filtering changes this list, not the next-class recommendation.');week.append(note);
 const filtered=plans.filter(c=>(!monthFilter||c.day.startsWith(monthFilter))&&(!weekFilter||academicWeek(c.day)===Number(weekFilter)));const status=document.createElement('p');status.id='scheduleFilterStatus';status.setAttribute('role','status');status.textContent=filtered.length+' / '+plans.length+' '+t('条行程','journeys');week.append(status);if(!filtered.length){const p=document.createElement('p');p.textContent=t('此月份和学周组合没有课程，可切换条件或显示全部。','No classes match this month and week. Change the filters or show all.');week.append(p);}let day='';for(const c of filtered){if(c.day!==day){const h=document.createElement('h3');const n=academicWeek(c.day);h.textContent=c.day+' · '+(n===0?t('开课前','Before teaching'):t('第','Week ')+n+t('周',''));week.append(h);day=c.day;}const row=document.createElement('article');row.className='auto-day';const info=document.createElement('div');const b=document.createElement('b');b.textContent=`${c.time} · ${c.title}`;const p=document.createElement('p');p.textContent=`${c.from} → ${c.building} · ${c.room||'—'} / ${modeName(c.mode)} / ${clock(c.depart)} ${t('出发','depart')}${c.conflict?' · '+t('课间衔接时间不足','Transfer buffer conflict'):''}`;info.append(b,p);row.append(info,button(t('查看','View'),()=>{choose(c);location.hash='/journey';}));week.append(row);}}
async function weather(){const seq=++weatherSeq;rain={};weatherStamp=0;if(!profile?.weather){$('autoWeatherState').textContent=t('天气监测未开启；当前计划未计天气因素。','Weather off; plans have no weather adjustment.');rebuild();return;}const courses=api.list();if(!courses.length)return;const lat=$('originLat').value,lon=$('originLon').value;$('autoWeatherState').textContent=t('正在读取天气预报…','Checking the forecast…');try{const u=new URL('https://api.open-meteo.com/v1/forecast');Object.entries({latitude:lat,longitude:lon,hourly:'precipitation_probability',timezone:'Europe/London',timeformat:'unixtime',forecast_days:7}).forEach(([k,v])=>u.searchParams.set(k,v));const r=await fetch(u,{signal:AbortSignal.timeout(12000)});if(!r.ok)throw Error();const j=await r.json();if(seq!==weatherSeq)return;for(const c of courses){const start=londonEpoch(c.day,c.time);const vals=j.hourly.time.flatMap((s,i)=>s*1000<start&&s*1000+3600000>start-(profile.minutes+profile.buffer+5)*60000&&Number.isFinite(j.hourly.precipitation_probability[i])?[j.hourly.precipitation_probability[i]]:[]);if(vals.length)rain[c.day]=(rain[c.day]||false)||vals.some(v=>v>=50);}weatherStamp=Date.now();$('autoWeatherState').textContent=t('天气已更新；未来7天内有覆盖的课程按降雨概率≥50%增加5分钟余量。其他日期天气未知。','Forecast updated; covered classes within 7 days use a 5-minute rain buffer at ≥50% rain chance. Other dates have unknown weather.');rebuild();}catch{if(seq!==weatherSeq)return;rain={};$('autoWeatherState').textContent=t('天气不可用；没有将缺失数据当作晴天。当前仅使用估计时间。','Weather unavailable; missing data is not treated as dry. Estimated times only.');rebuild();}}
$('profileForm').onsubmit=e=>{e.preventDefault();profile={name:$('profileName').value.trim(),origin:$('profileOrigin').value,mode:$('profileMode').value,minutes:Number($('profileMinutes').value),buffer:Number($('profileBuffer').value),campusMinutes:12,remember:$('profileRemember').checked,weather:$('profileWeather').checked,remind:$('profileRemind').checked};if(!profile.name)return;save();applyProfile();selected='';rebuild();weather();};
$('editProfile').onclick=()=>{if(!profile)return;for(const [id,val]of Object.entries({profileName:profile.name,profileOrigin:profile.origin,profileMode:profile.mode,profileMinutes:profile.minutes,profileBuffer:profile.buffer}))$(id).value=val;for(const [id,val]of Object.entries({profileRemember:profile.remember,profileWeather:profile.weather,profileRemind:profile.remind}))$(id).checked=!!val;$('autoSetup').hidden=false;$('autoDashboard').hidden=true;};
const prefCard=document.createElement('section');prefCard.className='route-card';prefCard.innerHTML=`<h2>${t('一次设置，持续衔接','Set once. Stay connected.')}</h2><p>${t('出发地区、偏好、天气授权和提醒统一由通勤档案管理。可随时修改或退出清除。','Origin, preferences, weather permission and reminders are managed together in the travel profile. Edit or sign out to clear it at any time.')}</p>`;prefCard.append(button(t('管理我的通勤档案','Manage travel profile'),()=>{$('editProfile').click();location.hash='/home';}));$('proactive').before(prefCard);$('proactive').hidden=true;
$('forgetProfile').onclick=()=>{stopTrip();weatherSeq++;profile=null;selected='';rain={};$('clearClasses').click();try{localStorage.removeItem(key);}catch{}$('reminderEnabled').checked=false;$('watchWeather').checked=false;$('reminderEnabled').dispatchEvent(new Event('change'));$('autoSetup').hidden=false;$('autoDashboard').hidden=true;$('profileForm').reset();};
function download(text,name,type){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([text],{type}));a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
$('importActions').append(button(t('下载 CSV 模板','Download CSV template'),()=>download('title,date,start,end,building,room\nExample class,2026-11-16,10:00,11:00,R16,\n','greengo-template.csv','text/csv')));
$('timetableFile').onchange=async()=>{preview=[];$('confirmImport').hidden=true;$('importPreview').replaceChildren();const file=$('timetableFile').files[0];if(!file)return;if(file.size>200000){$('importStatus').textContent=t('文件上限200KB。','Maximum file size 200 KB.');return;}try{preview=importCSV(await file.text(),Array.from($('building').options).map(o=>o.value));if(!preview.length)throw Error('No rows');for(const c of preview){const p=document.createElement('p');p.textContent=`${c.day} ${c.time}–${c.end} · ${c.title} · ${c.building} · ${c.room||'—'}`;$('importPreview').append(p);}$('importStatus').textContent=t('核对预览后确认。文件仅在本机解析。','Check the preview, then confirm. File parsed locally.');$('confirmImport').hidden=false;}catch(err){$('importStatus').textContent=t('无法导入，请检查列名、日期、时间和建筑编号。','Import failed: check headers, dates, times and building codes.')+' '+err.message;}};
$('confirmImport').onclick=()=>{try{const n=api.import(preview);$('importStatus').textContent=n+' '+t('节课程已导入，重复项已跳过。','classes imported; duplicates skipped.');preview=[];$('confirmImport').hidden=true;selected='';rebuild();weather();location.hash='/home';if(!profile)$('autoSetup').scrollIntoView();}catch(err){$('importStatus').textContent=err.message;}};
const stages=document.createElement('p');stages.textContent=t('校内转场暂按12分钟估计；可在详细行程中核对。首节课默认从档案出发地出发，后续课从上一教学楼衔接。','Campus transfers use a 12-minute estimate; verify in journey details. First class starts at the profile origin; later classes connect from the previous building.');$('autoWeek').after(stages);
let snooze=0,ignored='',alertKey='';
function tick(){if(!profile)return;if(weatherStamp&&Date.now()-weatherStamp>15*60000){rain={};weatherStamp=0;$('autoWeatherState').textContent=t('天气已过期，已移除天气调整；等待刷新。','Forecast expired; weather adjustments removed pending refresh.');rebuild();return;}if(active&&londonEpoch(active.day,active.time)<=Date.now()){selected='';rebuild();return;}const out=$('autoAlert');if(active&&profile.remind&&Date.now()>=active.depart-5*60000&&Date.now()<londonEpoch(active.day,active.time)&&Date.now()>=snooze&&ignored!==active.id){const k=active.id+':'+active.depart;if(k!==alertKey){alertKey=k;out.replaceChildren();const p=document.createElement('p');p.textContent=t('出发提醒：','Departure nudge: ')+active.title+' · '+clock(active.depart)+' · '+modeName(active.mode)+t('。以估计时间规划，请确认实际班次。','. Planned with estimated times; confirm services.');out.append(p,button(t('稍后5分钟','Snooze 5 min'),()=>{snooze=Date.now()+300000;alertKey='';out.replaceChildren();}),button(t('忽略本节','Ignore this class'),()=>{ignored=active.id;out.replaceChildren();}));}}if(trip){const elapsed=Math.floor((Date.now()-trip.started)/60000),remaining=Number($('tripRemaining').value),margin=Math.floor((trip.deadline-Date.now())/60000)-remaining;const guidance=margin<profile.buffer?t('余量不足，请核对后续交通或联系课程老师；无需冒险赶路。','Buffer low. Check onward travel or contact course staff; do not rush unsafely.'):t('按当前剩余时间估计，仍有课前余量。','The current remaining-time estimate leaves an arrival buffer.');$('tripStatus').textContent=`${t('已用时','Elapsed')} ${elapsed} min · ${t('课前余量','Buffer')} ${margin} min · ${guidance}`;}}
function stopTrip(){if(watch!==null){navigator.geolocation.clearWatch(watch);watch=null;}trip=null;$('tripTrace').hidden=true;$('tripTrace').querySelector('polyline').setAttribute('points','');$('gpsStatus').textContent='';}
$('tripActions').append(button(t('开始本次行程','Start this trip'),()=>{if(!active||active.day!==nowDay()){$('tripStatus').textContent=t('实际行程仅对今天的未来课程开放。','Start is available for upcoming classes today.');return;}stopTrip();trip={started:Date.now(),deadline:londonEpoch(active.day,active.time),points:[]};$('tripRemaining').value=active.duration;tick();},'primary'),button(t('开启本次 GPS 轨迹','Enable GPS for this trip'),()=>{if(!trip){$('gpsStatus').textContent=t('请先开始行程。','Start a trip first.');return;}if(!navigator.geolocation){$('gpsStatus').textContent=t('设备不支持定位。','Geolocation unavailable.');return;}if(watch!==null)return;watch=navigator.geolocation.watchPosition(p=>{if(!trip)return;if(p.coords.accuracy>60){$('gpsStatus').textContent=t('定位精度不足，暂不绘制此点。','Low location accuracy; this point is not drawn.');return;}trip.points.push([p.coords.longitude,p.coords.latitude]);trip.points=trip.points.slice(-500);const xs=trip.points.map(p=>p[0]),ys=trip.points.map(p=>p[1]),minx=Math.min(...xs),miny=Math.min(...ys),span=Math.max(Math.max(...xs)-minx,Math.max(...ys)-miny,.0001);$('tripTrace').querySelector('polyline').setAttribute('points',trip.points.map(p=>`${10+(p[0]-minx)/span*280},${90-(p[1]-miny)/span*80}`).join(' '));$('tripTrace').hidden=false;$('gpsStatus').textContent=t('本页 GPS 点数：','GPS points in this page: ')+trip.points.length+t('；不据此推断交通方式或 ETA。','; mode and ETA are not inferred.');},()=>{$('gpsStatus').textContent=t('定位被拒绝或不可用；可继续使用计时与手动剩余时间。','Location denied or unavailable. Timer and manual remaining time remain available.');if(watch!==null)navigator.geolocation.clearWatch(watch);watch=null;},{enableHighAccuracy:true,maximumAge:10000,timeout:15000});}),button(t('结束并清除轨迹','End & clear trace'),()=>{stopTrip();$('tripStatus').textContent=t('本次行程已结束，轨迹已清除。','Trip ended; trace cleared.');}));$('tripRemaining').oninput=tick;$('autoTrip').hidden=true;
window.addEventListener('greengo:class-selected',()=>{if(!auto)selected='';});new MutationObserver(()=>{selected='';rebuild();}).observe($('classList'),{childList:true});
try{const p=JSON.parse(localStorage.getItem(key)||'null');if(p&&typeof p.name==='string'&&Array.from($('area').options).some(o=>o.value===p.origin)&&['train','bus','walk','cycle'].includes(p.mode)&&Number.isFinite(p.minutes)&&p.minutes>=1&&p.minutes<=240&&Number.isFinite(p.buffer)&&p.buffer>=0&&p.buffer<=60){profile=p;applyProfile();rebuild();weather();}}catch{}
